#define STB_IMAGE_IMPLEMENTATION
#define STBI_ONLY_PNG
#include "stb/stb_image.h"
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <png_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *data = (unsigned char*)malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    int x, y, channels;
    if (!stbi_info_from_memory(data, size, &x, &y, &channels)) {
        printf("stbi_info_from_memory failed\n");
        free(data);
        return 0;
    }

    if (y && x > (80000000 / 4) / y) {
        printf("Image too large\n");
        free(data);
        return 0;
    }

    unsigned char *img = stbi_load_from_memory(data, size, &x, &y, &channels, 4);
    if (img) {
        printf("Loaded image: %dx%d, %d channels\n", x, y, channels);
        free(img);
    } else {
        printf("stbi_load_from_memory failed\n");
    }

    free(data);
    return 0;
}
EOF
